mapper.select:
SELECT * FROM recommendation_job
 WHERE requirement_id = #{requirementId}
 ORDER BY id DESC LIMIT 1

mapper.update:
UPDATE recommendation_job
   SET status = #{status}, finished_at = CURRENT_TIMESTAMP,
       error_message = #{errorMessage}, result_json = #{resultJson}
 WHERE id = #{id}

UPDATE recommendation_job
   SET status = 'FAILED', finished_at = CURRENT_TIMESTAMP, error_message = #{errorMessage}
 WHERE status IN ('PENDING', 'RUNNING')
